import { Component } from '@angular/core';
import { SolicitudApoyo } from '../../../../models/solicitud.apoyo';
import { ActivatedRoute } from '@angular/router';
import { SolicitudApoyoService } from '../../../../controllers/solicitud.apoyo.service';

import { FormModalidadDocumentoComponent } from "./form-modalidad-documento/form-modalidad-documento.component";
import { FormGroupComponent } from "../../../../shared/generic-form/form-group/form-group.component";
import { SolicitudApoyoModalidad } from '../../../../models/solicitud.apoyo.modalidad';
import { cartaCompromiso } from '../../../../services/documentosLegales/contratos/contrato_carta_compromiso.service';
import { ModalidadMinistracionDocumento } from '../../../../models/modalidad.ministracion.documento';
import { ModalidadMinistracionDocumentoService } from '../../../../controllers/modalidad.ministracion.documento.service';
import { SolicitudApoyoModalidadDocumento } from '../../../../models/solicitud.apoyo.modalidad.documento';
import { filter } from 'rxjs';

@Component({
    selector: 'app-form-apoyo-documentos',
    imports: [
    FormModalidadDocumentoComponent,
    FormGroupComponent
],
    templateUrl: './form-apoyo-documentos.component.html',
    styleUrl: './form-apoyo-documentos.component.css'
})
export class FormApoyoDocumentosComponent {
  solicitudApoyo?:SolicitudApoyo
  
  constructor(
    private route:ActivatedRoute,
    private solicitudApoyoController: SolicitudApoyoService,
    public cartaCompromiso: cartaCompromiso,
    private modalidadDocumentosController: ModalidadMinistracionDocumentoService,
  ){}

  ngOnInit(){
    this.route.parent?.params.subscribe(async (params) =>{
      const id = params['apoyo_id']
      if(id){
        this.solicitudApoyo= await this.solicitudApoyoController.find(id,[
          'solicitudesApoyosModalidades.modalidadesMinistraciones.programasApoyos',
          'solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades',
          'solicitudesApoyosModalidades.solicitudesApoyosModalidadesDocumentos.modalidadesMinistracionesDocumentos.documentos', 
          "solicitudesApoyosModalidades.solicitudesApoyosModalidadesDocumentos.modalidadesMinistracionesDocumentos.modalidadesMinistraciones",
          "solicitudesApoyosModalidades.solicitudesApoyosModalidadesDocumentos.modalidadesMinistracionesDocumentos.modalidadesMinistraciones.modalidades"
        ])

        this.verificarDocumentos()
      }
    })
  }

  private verificarDocumentos(){
    const toCreate:SolicitudApoyoModalidadDocumento[]=[]
    this.solicitudApoyo?.solicitudes_apoyos_modalidades?.forEach(async (solicitudModalidad)=>{
      const documentosModalidad = (await this.modalidadDocumentosController.all({
        modalidades_ministracion_id: solicitudModalidad.modalidades_ministracion_id,
      }, ['modalidadesMinistraciones.modalidades'])).filter((dm)=> dm.modalidades_ministraciones?.modalidad_id === solicitudModalidad.modalidades_ministraciones?.modalidad_id)
      console.log(documentosModalidad, solicitudModalidad)
      documentosModalidad.forEach( async (documentoModalidad)=>{
        const find = solicitudModalidad.solicitudes_apoyos_modalidades_documentos?.find((samd) => samd.modalidades_ministraciones_documento_id == documentoModalidad.id)
        if(!find){
          toCreate.push({
            solicitudes_apoyos_modalidad_id: solicitudModalidad.id,
            modalidades_ministraciones_documento_id: documentoModalidad.id,
            url: '',
            autorizado_por: 0,
            autorizado_fecha: '',
            usuario_id: 0,
            id: 0,
            created_at: ''
          })
        }
      })
    })
    console.info('TO CREATE:', toCreate)
  }

  modalidadDocumentoTitle(modalidad: SolicitudApoyoModalidad):string{
    return ((modalidad.modalidades_ministraciones?.programas_apoyos?.alias??'') +' - '+ (modalidad.modalidades_ministraciones?.modalidades?.nombre??'')).toUpperCase()
  }
}
