import { Component } from '@angular/core';
import { SolicitudApoyo } from '../../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../../controllers/solicitud.apoyo.service';
import { ActivatedRoute } from '@angular/router';
import { FormGroupComponent } from "../../../../shared/generic-form/form-group/form-group.component";
import { SolicitudApoyoModalidad } from '../../../../models/solicitud.apoyo.modalidad';
import { ModalidadCotizacionComponent } from "./modalidad-cotizacion/modalidad-cotizacion.component";

import { UtilsService } from '../../../../services/utils.service';


@Component({
  selector: 'app-form-apoyo-datos-bancarios',
  imports: [
    FormGroupComponent,
    ModalidadCotizacionComponent
  ],
  templateUrl: './form-apoyo-datos-bancarios.component.html',
  styleUrl: './form-apoyo-datos-bancarios.component.css'
})
export class FormApoyoDatosBancariosComponent {
  solicitudApoyo?: SolicitudApoyo

  constructor(
    private route: ActivatedRoute,
    private solicitudApoyoController: SolicitudApoyoService,
    public utils: UtilsService,
  ) { }

  ngOnInit() {
    this.route.parent?.params.subscribe(async (params) => {
      const id = params['apoyo_id']
      if (id) {
        this.solicitudApoyo = await this.solicitudApoyoController.find(id, [
          'solicitudesApoyosModalidades.modalidadesMinistraciones.programasApoyos',
          'solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades',
          'solicitudesApoyosModalidades.solicitudesApoyosModalidadesCotizaciones.apoyosProveedores',
        ])
        console.log('Solicitud de apoyo cargada:', this.solicitudApoyo);
      }
    })
  }

  modalidadDocumentoTitle(modalidad: SolicitudApoyoModalidad): string {
    return ((modalidad.modalidades_ministraciones?.programas_apoyos?.alias ?? '') + ' - ' + (modalidad.modalidades_ministraciones?.modalidades?.nombre ?? '')).toUpperCase()
  }

  public agregarCotizacion(modalidad: SolicitudApoyoModalidad) {
    if (!modalidad.solicitudes_apoyos_modalidades_cotizaciones) {
      modalidad.solicitudes_apoyos_modalidades_cotizaciones = []
    }
    modalidad.solicitudes_apoyos_modalidades_cotizaciones.push({
      solicitudes_apoyos_modalidad_id: modalidad.id,
      apoyos_proveedor_id: 0,
      monto: 0,
      autorizado_por: null,
      autorizado_fecha: null,
      documento_url: null,
      usuario_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
  }
}
