import { Component } from '@angular/core';
import { Form } from '../../../../shared/generic-form/generic-form.component';
import { ActivatedRoute } from '@angular/router';
import { SolicitudApoyoModalidad } from '../../../../models/solicitud.apoyo.modalidad';
import { SolicitudApoyoModalidadService } from '../../../../controllers/solicitud.apoyo.modalidad.service';

import { FormSolicitudModalidadComponent } from "./form-solicitud-modalidad/form-solicitud-modalidad.component";
import { UtilsService } from '../../../../services/utils.service';

const FORM_DEF:Form=[
  
]

@Component({
    selector: 'app-form-modalidades',
    imports: [
    FormSolicitudModalidadComponent
],
    templateUrl: './form-modalidades.component.html',
    styleUrl: './form-modalidades.component.css'
})
export class FormModalidadesComponent {
  solicitudApoyoId:number=0
  solicitudApoyoModalidades:SolicitudApoyoModalidad[]=[]
  
  isSomeEditing:boolean=false

  constructor(
    private solicitudApoyoModalidadController:SolicitudApoyoModalidadService,
    private route:ActivatedRoute,
    public utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.parent?.params.subscribe(async (params)=>{
      const id= params['apoyo_id']
      if(id){
        this.solicitudApoyoId=id
        this.solicitudApoyoModalidades= await this.solicitudApoyoModalidadController.all({solicitudes_apoyo_id:id,deleted_at:null},['modalidadesMinistraciones.programasApoyos','modalidadesMinistraciones.modalidades'])
      }
    })
  }

  someModalidadIsActive(){
    return this.solicitudApoyoModalidades.some(mod => mod.estado!=='CONCLUIDO')
  }

  agregarModalidad(){
    this.isSomeEditing=true
    this.solicitudApoyoModalidades.push({
      solicitudes_apoyo_id: this.solicitudApoyoId,
      sesion_id: null,
      modalidades_ministracion_id: 0,
      estado: 'CAPTURANDO',
      carta_instruccion_url: null,
      usuario_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })

  }
}
