import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { AutocompleteFieldComponent } from "../generic-form/autocomplete-field/autocomplete-field.component";
import { DataViewSectionComponent } from "../data-view-section/data-view.component";
import { DatoPersonal } from '../../models/dato.personal.model';
import { DatoPersonalService } from '../../controllers/dato.personal.service';

import { TablaLocalComponent } from "../tabla-local/tabla-local.component";

@Component({
    selector: 'app-select-datos-personales',
    imports: [
    AutocompleteFieldComponent,
    DataViewSectionComponent,
    TablaLocalComponent
],
    templateUrl: './select-datos-personales.component.html',
    styleUrl: './select-datos-personales.component.css'
})
export class SelectDatosPersonalesComponent {
  @Input() datoPersonalId?:number|null
  @Output() datoPersonalIdChange = new EventEmitter<number>()
  @Input() datoPersonal?:DatoPersonal
  @Output() datoPersonalChange= new EventEmitter<DatoPersonal>()

  @Input() searchLabel:string='¿El solicitante existe en el sistema?'

  constructor(
    private dpController:DatoPersonalService,
  ){}

  ngOnChanges( changes:SimpleChanges){
    if(changes['datoPersonalId'] && this.datoPersonalId){
      this.setDatosPersonales(this.datoPersonalId)
    }
  }

  async setDatosPersonales(id:string|number|null){
    if(typeof id =='number'){
      this.datoPersonal = await this.dpController.find(id, ['creditos', 'creditosPf', 'creditosPm', 'telefonosPersonales','ciudades','estado_nacimiento','solicitudesApoyos', 'modalidadesMinistraciones'], false);
      return
    }
    this.datoPersonal=undefined
  }

  onSelected(){
    this.datoPersonalChange.emit(this.datoPersonal)
    this.datoPersonalIdChange.emit(this.datoPersonal?.id)
  }
}
