import { Component, EventEmitter, Input, Output } from '@angular/core';
import { SolicitudApoyoModalidad } from '../../../../../models/solicitud.apoyo.modalidad';
import { AutocompleteFieldComponent } from "../../../../../shared/generic-form/autocomplete-field/autocomplete-field.component";

import { SolicitudApoyoModalidadService } from '../../../../../controllers/solicitud.apoyo.modalidad.service';
import { ModalidadMinistracionService } from '../../../../../controllers/modalidad.ministracion.service';
import { ActivatedRoute } from '@angular/router';
import { SolicitudApoyoService } from '../../../../../controllers/solicitud.apoyo.service';
import { ModalidadMinistracion } from '../../../../../models/modalidad.ministracion';

@Component({
    selector: 'app-form-solicitud-modalidad',
    imports: [
    AutocompleteFieldComponent
],
    templateUrl: './form-solicitud-modalidad.component.html',
    styleUrl: './form-solicitud-modalidad.component.css'
})
export class FormSolicitudModalidadComponent {
  @Input() solicitudApoyoModalidad!:SolicitudApoyoModalidad&{id:number}
  @Output() onDeleted= new EventEmitter()
  @Output() onSaved= new EventEmitter()
  
  solicitudApoyoId:number=0

  modalidadMask= (row:ModalidadMinistracion) =>{
    return row.modalidades!.nombre
  }

  edit=false
  isLoading:boolean=false
  isDeleting=false

  autoCompleteExtra:any={}

  constructor(
    private solicitudApoyoController: SolicitudApoyoService,
    private solicitudApoyoModalidadController: SolicitudApoyoModalidadService,
    private modalidadesController: ModalidadMinistracionService,
    private route: ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.parent?.params.subscribe((params)=>{ this.solicitudApoyoId= params['apoyo_id']})
    if(!this.solicitudApoyoModalidad.id) this.edit=true;
    this.setFilters()
  }

  private async setFilters(){
    if(this.solicitudApoyoModalidad.id){
      this.autoCompleteExtra={
        conditionals:JSON.stringify([
          ['programas_apoyo_id','=',this.solicitudApoyoModalidad.modalidades_ministraciones?.programas_apoyo_id],
          ['deleted_at','IS NULL',null],
        ])
      }
      return
    }
    if(!this.solicitudApoyoId) return
    const solicitud = await this.solicitudApoyoController.find(this.solicitudApoyoId)
    if(!solicitud) return
    this.autoCompleteExtra={
      conditionals:JSON.stringify([
        ['programas_apoyo_id','=',solicitud.programas_apoyo_id],
        ['deleted_at','IS NULL',null],
      ])
    }
  }

  public async save(){
    this.isLoading=true
    const res= await this.solicitudApoyoModalidadController.createOrUpdate(this.solicitudApoyoModalidad)
    if(res){
      this.solicitudApoyoModalidad.id=res.id
      this.solicitudApoyoModalidad.modalidades_ministraciones= await this.modalidadesController.find(res.modalidades_ministracion_id,['programasApoyos','modalidades'])
      this.onSaved.emit()
    }
    this.edit=false
    this.isLoading=false
  }

  public async delete(){
    this.isDeleting=true
    if(!this.solicitudApoyoModalidad.id){
      this.onDeleted.emit()
      return
    }
    const res= await this.solicitudApoyoModalidadController.switch(this.solicitudApoyoModalidad)
    if(res){
      this.onDeleted.emit()
    }
    this.isDeleting=false
  }
}