import { Component } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { ApoyoTipoInversion } from '../../../../models/apoyo.tipo.inversion';
import { ApoyoTipoInversionService } from '../../../../controllers/apoyo.tipo.inversion.service';
import { UtilsService } from '../../../../services/utils.service';
import { FormInversionTipoComponent } from "./form-inversion-tipo/form-inversion-tipo.component";
import { CurrencyPipe } from '@angular/common';
import { ModalidadMinistracion } from '../../../../models/modalidad.ministracion';
import { SolicitudApoyoModalidadService } from '../../../../controllers/solicitud.apoyo.modalidad.service';
import { SolicitudApoyoModalidad } from '../../../../models/solicitud.apoyo.modalidad';
import { SolicitudApoyo } from '../../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../../controllers/solicitud.apoyo.service';

@Component({
    selector: 'app-form-apoyo-inversion',
    imports: [
    FormInversionTipoComponent,
    CurrencyPipe
],
    templateUrl: './form-apoyo-inversion.component.html',
    styleUrl: './form-apoyo-inversion.component.css'
})
export class FormApoyoInversionComponent {
  solicitudApoyoId:number=0
  solicitudApoyo?:SolicitudApoyo
  apoyoTiposInversiones: ApoyoTipoInversion[]=[]
  modalidadActual?:SolicitudApoyoModalidad

  isSomeEditing=false

  constructor(
    private solicitudApoyoController: SolicitudApoyoService,
    private route: ActivatedRoute,
    public utils:UtilsService,
  ){}

  ngOnInit(){
    this.route.parent?.params.subscribe(async (params)=>{
      const id= params['apoyo_id']
      if(id){
        this.solicitudApoyoId=id
        this.solicitudApoyo= await this.solicitudApoyoController.find(this.solicitudApoyoId,[
          'solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades',
          "apoyosTiposInversiones.apoyosTiposInversionesDetalles",
        ])
        this.apoyoTiposInversiones= this.solicitudApoyoController.tiposInversionesActuales(this.solicitudApoyo, this.modalidadActual)
        this.modalidadActual= this.solicitudApoyoController.modalidadActual(this.solicitudApoyo)
        console.log(this.modalidadActual)
      }
    })
  }

  agregarTipoInversion(){
    this.isSomeEditing=true
    this.apoyoTiposInversiones.push({
      solicitudes_apoyo_id: this.solicitudApoyoId,
      solicitud_modalidad_id: this.modalidadActual!.id,
      inversion_tipo: 'MERCANCIA E INSUMOS',
      usuario_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
  }

  public total():number{
    return this.apoyoTiposInversiones.reduce((acc,tipo)=>{
      return acc+(tipo.apoyos_tipos_inversiones_detalles??[]).reduce((acc,detalle)=>{
        return acc + +detalle.monto_solicitado
      },0)
    },0)
  }
}
