import { Component } from '@angular/core';
import { ApoyoTipoInversion } from '../../../../../models/apoyo.tipo.inversion';
import { RecordFormComponent } from '../../../../../shared/record-form/record-form.component';
import { CurrencyPipe } from '@angular/common';
import { ApoyoTipoInversionService } from '../../../../../controllers/apoyo.tipo.inversion.service';
import { SelectFieldComponent } from "../../../../../shared/generic-form/select-field/select-field.component";
import { RecordFormButtonsComponent } from "../../../../../shared/record-form/record-form-buttons/record-form-buttons.component";
import { ApoyoTipoInversionDetalle } from '../../../../../models/apoyo.tipo.inversion.detalle';
import { FormInversionDetalleComponent } from "../form-inversion-detalle/form-inversion-detalle.component";
import { UtilsService } from '../../../../../services/utils.service';

@Component({
    selector: 'app-form-inversion-tipo',
    imports: [
    SelectFieldComponent,
    RecordFormButtonsComponent,
    CurrencyPipe,
    FormInversionDetalleComponent
],
    templateUrl: './form-inversion-tipo.component.html',
    styleUrl: './form-inversion-tipo.component.css'
})
export class FormInversionTipoComponent extends RecordFormComponent<ApoyoTipoInversion> {
  showDetalles=false

  isSomeChildEditing=false
  detalles:ApoyoTipoInversionDetalle[]=[]

  constructor(
    private apoyoTipoInversionController:ApoyoTipoInversionService,
    public utils:UtilsService,
  ){
    super(apoyoTipoInversionController);
  }

  override async ngOnInit() {
    await this.save()
    this.checkIfIsEditing()
    if(this.record.id){
      this.detalles=this.record.apoyos_tipos_inversiones_detalles??[]
    }
  }

  public subTotal():number{
    return this.detalles.reduce((acc,item)=>{
      return acc+ +item.monto_solicitado
    },0)
  }

  public agregarDetalle(){
    this.showDetalles=true
    this.detalles.push({
      apoyos_tipos_inversion_id: this.record.id,
      nombre: '',
      monto_solicitado: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
    this.record.apoyos_tipos_inversiones_detalles=this.detalles
  }
}
